cd /tmp; rm -f cj.txt; echo "== GET login =="; curl -s -c cj.txt -o login.html -w "%{http_code}
" http://tfm-fachplanung.ddev.site/login; echo "== POST login =="; curl -s -b cj.txt -c cj.txt -o post.html -w "%{http_code} -> %{redirect_url}
" -d "user=r1_user&pass=r1_password&login-submit=Anmelden" http://tfm-fachplanung.ddev.site/login; echo "== follow =="; curl -s -b cj.txt -c cj.txt -o after.html -w "%{http_code}
" -L http://tfm-fachplanung.ddev.site/; echo "== after title =="; grep -io '<title>[^<]*</title>' after.html; echo "== errors =="; grep -ioE '(Fehler|ungültig|falsch|Anmeldung fehlgeschlagen)[^<]*' post.html after.html | head
